// Infill front end.
// Data: data/cities.js (index) + data/cities/<slug>.js, generated by scripts/build_sites.py from public data.
// Team state (rail stations + site visits) lives in pipeline.json via scripts/serve.py,
// or in this browser's localStorage when the page is opened as a plain file.

const FLAGS = {
  open:         "Still available (mostly open / active notice)",
  low_income:   "City listed lower-income capacity",
  no_flood:     "Not in a flood hazard area",
  no_fire:      "Not in a fire hazard zone",
  near_transit: "Inside a high-quality transit area",
};
const STATIONS = [
  ["screened", "Screened"], ["to_call", "To call"], ["called", "Called"],
  ["visit", "Site visit"], ["surveyed", "Surveyed"], ["pursuing", "Pursuing"], ["dropped", "Dropped"],
];
const FOUND = [
  ["vacant", "Vacant land", "open"], ["parking", "Surface parking", "open"],
  ["small_bldg", "Small building(s), most of lot open", "partly"], ["built", "Built out / occupied", "built"],
  ["construction", "Under construction", "built"], ["other", "Other (see note)", "unknown"],
];
const STATUS_WORD = { pass: "Pass", fail: "Fail", unknown: "Unknown" };
const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));

// ---------- icons (inline stroke SVG, per the design system) ----------
const IC = {
  pass: (c = "#FFFFFF", s = 14) => `<svg width="${s}" height="${s}" viewBox="0 0 16 16" fill="none" stroke="${c}" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 8.5l3.2 3L13 4.5"/></svg>`,
  fail: (c = "#FFFFFF", s = 14) => `<svg width="${s}" height="${s}" viewBox="0 0 16 16" fill="none" stroke="${c}" stroke-width="2.6" stroke-linecap="round" aria-hidden="true"><path d="M4 4l8 8M12 4l-8 8"/></svg>`,
  unknown: (c = "#FFFFFF", s = 14) => `<svg width="${s}" height="${s}" viewBox="0 0 16 16" fill="none" stroke="${c}" stroke-width="2.6" stroke-linecap="round" aria-hidden="true"><path d="M5.6 5.8a2.4 2.4 0 1 1 3.4 2.2c-.7.3-1 .8-1 1.5v.4"/><circle cx="8" cy="13" r="0.9" fill="${c}" stroke="none"/></svg>`,
  close: `<svg width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="#1B1F1D" stroke-width="2" stroke-linecap="round" aria-hidden="true"><path d="M4 4l8 8M12 4l-8 8"/></svg>`,
  star: (on, c) => `<svg width="18" height="18" viewBox="0 0 16 16" fill="${on ? (c || "#FFFFFF") : "none"}" stroke="${c || (on ? "#FFFFFF" : "#1B1F1D")}" stroke-width="1.5" stroke-linejoin="round" aria-hidden="true"><path d="M8 1.8l1.9 3.9 4.3.6-3.1 3 .7 4.3L8 11.6l-3.8 2 .7-4.3-3.1-3 4.3-.6z"/></svg>`,
};
const STATION_ICON = {
  to_call: (c) => `<svg width="13" height="13" viewBox="0 0 16 16" fill="none" stroke="${c}" stroke-width="1.6" stroke-linejoin="round" aria-hidden="true"><path d="M3.5 2.5h3l1.2 3-1.7 1.1a8 8 0 0 0 3.4 3.4l1.1-1.7 3 1.2v3a1 1 0 0 1-1 1A11.5 11.5 0 0 1 2.5 3.5a1 1 0 0 1 1-1z"/></svg>`,
  called: (c) => `<svg width="13" height="13" viewBox="0 0 16 16" fill="none" stroke="${c}" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M2.5 8.5l3 3 8-8"/></svg>`,
  visit: (c) => `<svg width="13" height="13" viewBox="0 0 16 16" fill="none" stroke="${c}" stroke-width="1.6" aria-hidden="true"><path d="M8 14.5s4.5-4.3 4.5-8a4.5 4.5 0 0 0-9 0c0 3.7 4.5 8 4.5 8z"/><circle cx="8" cy="6.5" r="1.5"/></svg>`,
  surveyed: (c) => `<svg width="13" height="13" viewBox="0 0 16 16" fill="none" stroke="${c}" stroke-width="1.6" stroke-linejoin="round" aria-hidden="true"><path d="M8 1.8l5.5 3.1v6.2L8 14.2l-5.5-3.1V4.9z"/><path d="M2.5 4.9L8 8l5.5-3.1M8 8v6.2"/></svg>`,
  pursuing: (c) => `<svg width="13" height="13" viewBox="0 0 16 16" fill="none" stroke="${c}" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M2.5 8h10M9 4.5L12.5 8 9 11.5"/></svg>`,
  dropped: (c) => `<svg width="13" height="13" viewBox="0 0 16 16" fill="none" stroke="${c}" stroke-width="1.6" aria-hidden="true"><circle cx="8" cy="8" r="5.5"/><path d="M4.2 11.8l7.6-7.6"/></svg>`,
  screened: (c) => `<svg width="13" height="13" viewBox="0 0 16 16" fill="none" stroke="${c}" stroke-width="1.6" aria-hidden="true"><path d="M2 3h12l-4.5 5.5V13l-3 1.5V8.5z"/></svg>`,
};
const STATION_FG = { to_call: "#FFFFFF", pursuing: "#FFFFFF", dropped: "#575C55", screened: "#575C55" };
const stationName = (k) => (STATIONS.find((s) => s[0] === k) || [k, k])[1];
const tag = (k, sm) => `<span class="tag ${k} ${sm ? "sm" : ""}">${STATION_ICON[k] ? STATION_ICON[k](STATION_FG[k] || "#1B1F1D") : ""}${stationName(k)}</span>`;
const bars = (level, c) => {
  const f = (x, y, w, h, on) => on ? `<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${c}"/>` : `<rect x="${x + 0.5}" y="${y + 0.5}" width="${w - 1}" height="${h - 1}" fill="none" stroke="${c}" stroke-width="1"/>`;
  const n = { high: 3, medium: 2, low: 1 }[level] || 1;
  return `<svg width="12" height="12" viewBox="0 0 12 12" aria-hidden="true">${f(0, 7, 3, 5, n >= 1)}${f(4.5, 4, 3, 8, n >= 2)}${f(9, 1, 3, 11, n >= 3)}</svg>`;
};
const pill = (level, sm, word) => {
  const c = level === "high" ? "#FFFFFF" : (level === "medium" ? "#1B1F1D" : "#575C55");
  const w = word || ({ high: "High conf.", medium: "Med conf.", low: "Low conf." }[level] || level);
  return `<span class="pill ${level} ${sm ? "sm" : ""}">${bars(level, c)}${w}</span>`;
};
const plateText = (p) => p.kind === "surplus" ? "SL" : (p.kind === "checked" ? "CK" : String(p.rank).padStart(2, "0"));
const counts = (p) => {
  const n = { pass: 0, fail: 0, unknown: 0 };
  for (const c of p.checks || []) n[c.status]++;
  return `<span class="counts" aria-label="${n.pass} pass, ${n.fail} fail, ${n.unknown} unknown"><span>${IC.pass("#0A6B48", 12)}${n.pass}</span><span>${IC.fail("#B3261E", 12)}${n.fail}</span><span>${IC.unknown("#5F635E", 12)}${n.unknown}</span></span>`;
};

// ---------- city data ----------
const CITY_INDEX = window.INFILL_CITY_INDEX || [];
let city = null, meta = {}, sites = [], surplus = [], checked = [], byId = {};
function loadCity(slug) {
  return new Promise((resolve, reject) => {
    if (window.INFILL_CITIES?.[slug]) return resolve(window.INFILL_CITIES[slug]);
    const s = document.createElement("script");
    s.src = `data/cities/${slug}.js`;
    s.onload = () => resolve(window.INFILL_CITIES[slug]);
    s.onerror = () => reject(new Error(`data/cities/${slug}.js not found`));
    document.head.appendChild(s);
  });
}
async function useCity(slug) {
  const d = await loadCity(slug);
  city = slug; meta = d.meta; sites = d.sites.features; surplus = (d.surplus || {}).features || [];
  checked = [];
  byId = Object.fromEntries([...sites, ...surplus].map((f) => [f.properties.id, f]));
  gridSetup();
  selectedId = null; document.getElementById("card").style.display = "none";
  try { localStorage.setItem("infill-city", slug); } catch {}
  renderAll();
  fitToPins();
}
function fitToPins() {
  const fs = [...shownSites(), ...shownSurplus()];
  if (!fs.length) { map.setView(meta.center, meta.zoom || 13); return; }
  const b = L.geoJSON({ type: "FeatureCollection", features: fs }).getBounds();
  map.fitBounds(b, { paddingTopLeft: [60, 60], paddingBottomRight: [60, 60], maxZoom: 15 });
}

// Grid reference on our own 8x8 grid over the city's sites (Thomas Guide style, not Thomas Guide pages)
let gridBox = null;
function gridSetup() {
  const pts = sites.map((f) => L.geoJSON(f).getBounds().getCenter());
  if (!pts.length) { gridBox = null; return; }
  const lats = pts.map((p) => p.lat), lngs = pts.map((p) => p.lng);
  gridBox = [Math.min(...lngs), Math.min(...lats), Math.max(...lngs), Math.max(...lats)];
}
function gridRef(f) {
  if (!gridBox) return "";
  const c = f.geometry.type === "Point" ? { lng: f.geometry.coordinates[0], lat: f.geometry.coordinates[1] } : L.geoJSON(f).getBounds().getCenter();
  const fx = Math.min(7, Math.max(0, Math.floor(((c.lng - gridBox[0]) / ((gridBox[2] - gridBox[0]) || 1)) * 8)));
  const fy = Math.min(7, Math.max(0, Math.floor(((gridBox[3] - c.lat) / ((gridBox[3] - gridBox[1]) || 1)) * 8)));
  return `GRID ${"ABCDEFGH"[fx]}${fy + 1}`;
}

// ---------- team state ----------
let server = false, claudeOn = false, state = {};
const LS = "infill-pipeline-v1";
async function loadState() {
  try {
    const h = await (await fetch("/api/health")).json();
    server = !!h.ok; claudeOn = !!h.claude;
    state = await (await fetch("/api/pipeline")).json();
  } catch { try { state = JSON.parse(localStorage.getItem(LS) || "{}"); } catch { state = {}; } }
}
async function saveState() {
  if (server) { try { await fetch("/api/pipeline", { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify(state) }); return; } catch {} }
  try { localStorage.setItem(LS, JSON.stringify(state)); } catch {}
}
const siteState = (id) => (state[id] ||= { station: byId[id]?.properties.top ? "to_call" : "screened", visits: [], log: [] });
const peekStation = (id) => state[id]?.station || (byId[id]?.properties.top ? "to_call" : "screened");
function setStation(id, st, why) {
  const s = siteState(id);
  if (s.station === st) return;
  s.log.push({ at: new Date().toISOString(), from: s.station, to: st, why: why || "" });
  s.station = st; saveState(); renderAll();
}
function predicted(p) {
  const av = (p.checks || []).filter((c) => c.group === "Still available?").map((c) => c.status);
  if (av.includes("pass") && !av.includes("fail")) return "open";
  if (av.includes("fail")) return "built";
  return "unknown";
}
function verdict(p, v) {
  const fv = FOUND.find((x) => x[0] === v.found), found = (fv || [])[2] || "unknown";
  const pred = predicted(p);
  if (pred === "unknown" || found === "unknown") return { kind: "new", text: "The data couldn't tell. The visit settles it." };
  if (pred === found || (pred === "open" && found === "partly")) return { kind: "match", text: "The visit matches what the data predicted." };
  return { kind: "miss", text: `Data predicted "${pred === "open" ? "mostly open" : "built out"}", visit found "${fv ? fv[1] : v.found}".` };
}

// ---------- map ----------
const map = L.map("map", { zoomControl: true }).setView([33.835, -117.914], 12);
const BASEMAPS = [
  ["https://tile.openstreetmap.org/{z}/{x}/{y}.png", '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors', 19],
  ["https://server.arcgisonline.com/ArcGIS/rest/services/Canvas/World_Light_Gray_Base/MapServer/tile/{z}/{y}/{x}", "Tiles &copy; Esri", 16],
];
let baseIdx = 0, baseErrors = 0, base;
function setBase(i) {
  if (base) map.removeLayer(base);
  const [url, attribution, maxZoom] = BASEMAPS[i];
  base = L.tileLayer(url, { attribution, maxZoom: 19, maxNativeZoom: maxZoom }).addTo(map);
  base.bringToBack();
  base.on("tileerror", () => { if (++baseErrors > 4 && baseIdx < BASEMAPS.length - 1) { baseErrors = 0; setBase(++baseIdx); } });
}
setBase(0);

let topOnly = true, view = "map", showSurplus = true, showArchived = true;
const active = new Set();
const filtersEl = document.getElementById("filters");
for (const [k, label] of Object.entries(FLAGS)) {
  const l = document.createElement("label");
  l.className = "check";
  l.innerHTML = `<input type="checkbox" data-k="${k}"> ${label}`;
  l.querySelector("input").onchange = (e) => { e.target.checked ? active.add(k) : active.delete(k); renderAll(); };
  filtersEl.appendChild(l);
}
document.querySelectorAll(".segmented button").forEach((b) => (b.onclick = () => {
  topOnly = b.dataset.top === "1";
  document.querySelectorAll(".segmented button").forEach((x) => x.setAttribute("aria-pressed", String(x === b)));
  renderAll(); fitToPins();
}));
document.getElementById("showSurplus").onchange = (e) => { showSurplus = e.target.checked; renderAll(); };
document.getElementById("showArchived").onchange = (e) => { showArchived = e.target.checked; renderAll(); };
const citySel = document.getElementById("city");
citySel.innerHTML = CITY_INDEX.map((c) => `<option value="${c.slug}">${esc(c.city)} · ${c.count} sites${c.surplus ? ` · ${c.surplus} surplus` : ""}</option>`).join("");
citySel.onchange = () => useCity(citySel.value);

let layer = L.layerGroup().addTo(map), selectedId = null;
const passes = (f) => [...active].every((k) => (f.properties.flags || {})[k]);
const shownSites = () => sites.filter((f) => (!topOnly || f.properties.top) && passes(f)).sort((a, b) => a.properties.rank - b.properties.rank);
const shownSurplus = () => showSurplus ? surplus.filter((f) => (showArchived || f.properties.active) && passes(f)) : [];

function drawMap(ss, sp) {
  layer.clearLayers();
  const sel = selectedId && byId[selectedId];
  L.geoJSON({ type: "FeatureCollection", features: ss }, {
    bubblingMouseEvents: false,
    style: (f) => ({ color: "#1A3C8F", weight: 2, fillColor: "#2450B8", fillOpacity: 0.4,
                     dashArray: peekStation(f.properties.id) === "dropped" ? "4 4" : null }),
    onEachFeature: (f, l) => {
      l.on("click", () => select(f.properties.id));
      l.on("mouseover", () => l.setStyle({ weight: 2.5, fillOpacity: 0.5 }));
      l.on("mouseout", () => l.setStyle({ weight: 2, fillOpacity: 0.4 }));
      l.bindTooltip(`${plateText(f.properties)} · ${f.properties.label}`);
    },
  }).addTo(layer);
  for (const f of checked) {
    L.geoJSON(f, { bubblingMouseEvents: false, style: { color: "#1B1F1D", weight: f.properties.id === selectedId ? 3 : 2, dashArray: "6 4", fillColor: "#1B1F1D", fillOpacity: 0.12 },
      onEachFeature: (ff, l) => { l.on("click", () => select(ff.properties.id)); l.bindTooltip(`CK · ${ff.properties.label}`); } }).addTo(layer);
  }
  if (sel && sel.geometry.type !== "Point" && ss.includes(sel)) {
    L.geoJSON(sel, { style: { color: "#FFFFFF", weight: 7, fillOpacity: 0 }, interactive: false }).addTo(layer);
    L.geoJSON(sel, { style: { color: "#0E1F4D", weight: 3, fillColor: "#2450B8", fillOpacity: 0.55 }, interactive: false }).addTo(layer);
  }
  // Pins: lot outlines are too small to see at city zoom, so every site also gets a pin.
  // Top 10 get numbered rank plates; the rest get small dots so big cities stay readable.
  for (const f of ss) {
    const p = f.properties, c = L.geoJSON(f).getBounds().getCenter();
    const on = p.id === selectedId, dropped = peekStation(p.id) === "dropped";
    const plate = p.top || ss.length <= 25;
    const icon = plate
      ? L.divIcon({ className: "", html: `<div class="rank-pin ${on ? "on" : ""} ${dropped ? "dropped" : ""}">${plateText(p)}</div>`, iconSize: [30, 24], iconAnchor: [15, 12] })
      : L.divIcon({ className: "", html: `<div class="dot-pin ${on ? "on" : ""} ${dropped ? "dropped" : ""}"></div>`, iconSize: on ? [16, 16] : [12, 12], iconAnchor: on ? [8, 8] : [6, 6] });
    L.marker(c, { icon, keyboard: true, title: `${plateText(p)} · ${p.label}`, zIndexOffset: on ? 2000 : (plate ? 1000 - (p.rank || 0) : 0) })
      .on("click", () => select(p.id)).bindTooltip(`${plateText(p)} · ${p.label}`, { direction: "top", offset: [0, -10] }).addTo(layer);
  }
  for (const f of sp) {
    const p = f.properties, [lng, lat] = f.geometry.coordinates, on = p.id === selectedId;
    const icon = L.divIcon({ className: "", html: `<div class="surplus-pin ${p.active ? "" : "archived"} ${on ? "on" : ""}"></div>`, iconSize: [18, 18], iconAnchor: [9, 9] });
    L.marker([lat, lng], { icon, keyboard: true, title: `SL · ${p.label}`, zIndexOffset: on ? 2000 : 500 })
      .on("click", () => select(p.id)).bindTooltip(`SL · ${p.label}${p.active ? "" : " · archived"}`, { direction: "top", offset: [0, -10] }).addTo(layer);
  }
}

const defaultStation = (id) => (byId[id] ? (byId[id].properties.top ? "to_call" : "screened") : (state[id]?.station || "screened"));
const isSaved = (id) => !!state[id]?.saved;
function rowHTML(f) {
  const p = f.properties, st = peekStation(p.id), moved = st !== defaultStation(p.id);
  return `<button type="button" class="list-row ${p.id === selectedId ? "on" : ""}" data-id="${p.id}">
    <span class="plate ${p.kind || ""}">${plateText(p)}</span>
    <span class="lr-main">
      <span class="lr-top"><span class="lr-apn">${esc(p.apn || p.label)}</span>${pill(p.confidence, true, { high: "High", medium: "Med", low: "Low" }[p.confidence])}${moved ? tag(st, true) : ""}${isSaved(p.id) ? `<span class="saved-mark" aria-label="Saved">${IC.star(true, "#1B1F1D")}</span>` : ""}</span>
      <span class="lr-sum">${esc(p.summary)}</span>
    </span>
    <span class="lr-side">${counts(p)}<span class="meta">${p.acres != null ? p.acres + " ac" : "? ac"}</span></span>
  </button>`;
}

function renderList() {
  const ss = shownSites(), sp = shownSurplus();
  drawMap(ss, sp);
  document.getElementById("count").textContent = meta.city
    ? `${ss.length} of ${sites.length} housing-element sites${showSurplus ? ` · ${sp.length} surplus notices` : ""} · ${meta.city} · data pulled ${meta.pulled}`
    : "";
  const list = document.getElementById("list");
  if (!sites.length) {
    list.innerHTML = '<div class="empty">No data loaded yet. Run <span class="mono">python3 scripts/fetch_data.py</span> then <span class="mono">python3 scripts/build_sites.py</span>.</div>';
    return;
  }
  list.innerHTML = (ss.length ? ss.slice(0, 300).map(rowHTML).join("") : '<div class="empty">No housing-element sites pass every selected check.</div>') +
    (checked.length ? `<div class="label" style="padding:16px 12px 4px">Lots you checked · ${checked.length}</div>` + checked.map(rowHTML).join("") : "") +
    (sp.length ? `<div class="label" style="padding:16px 12px 4px">Surplus public land · ${sp.length}</div>` + sp.map(rowHTML).join("") : "") +
    `<div class="foot"><span class="label">Sources</span> · checked ${esc(meta.sources?.[0]?.checked || "?")}<br>` +
    (meta.sources || []).map((s) => `<a href="${s.url}" target="_blank" rel="noopener">${esc(s.name)}</a>`).join("<br>") +
    `<br><br><span class="label">How sites are ranked</span><br>${esc(meta.ranking || "")}` +
    `<br><br>Team notes are saved ${server ? "to pipeline.json on this computer" : "in this browser only (run scripts/serve.py to share)"}. Grid references are Infill's own 8×8 grid over the city's sites.` +
    `<br>Prototype. Screening only, not a zoning or legal determination.</div>`;
  list.querySelectorAll(".list-row").forEach((b) => (b.onclick = () => select(b.dataset.id, true)));
}

// ---------- rail ----------
function renderRail() {
  const el = document.getElementById("rail");
  const all = [...sites, ...surplus, ...checked];
  const tracked = all.filter((f) => peekStation(f.properties.id) !== "screened");
  const cols = STATIONS.filter(([k]) => k !== "screened");
  el.innerHTML = `<div class="pane-head"><h2>Rail · ${esc(meta.city || "")}</h2><span class="meta">${tracked.length} sites in play · move a ticket from its card · every move is logged with a reason</span></div>
    <div class="rail-wrap"><div class="rail-bar"></div><div class="rail-cols">` + cols.map(([k]) => {
      const items = tracked.filter((f) => peekStation(f.properties.id) === k).sort((a, b) => (a.properties.rank || 999) - (b.properties.rank || 999));
      return `<div class="rail-col"><div class="row-between">${tag(k)}<span class="mono" style="font-weight:600">${items.length}</span></div>` + items.map((f) => {
        const p = f.properties, s = state[p.id], last = s?.visits?.[s.visits.length - 1];
        const moved = s?.log?.length ? s.log[s.log.length - 1].at : null;
        const age = moved ? Math.max(0, Math.round((Date.now() - Date.parse(moved)) / 86400000)) + "d" : "";
        return `<button type="button" class="ticket ${k} ${p.id === selectedId ? "on" : ""}" data-id="${p.id}">
          <span class="row-between mono" style="font-size:12px"><b>#${plateText(p)}</b><span class="meta">${age}</span></span>
          <span class="t-name">${esc(p.kind === "surplus" ? p.label : (p.low_income_capacity + " lower-income homes"))}</span>
          <span class="meta">${esc(p.apn || "")}${p.acres != null ? ` · ${p.acres} ac` : ""}</span>
          ${last ? `<span class="meta">Visited ${esc(last.date)}${last.survey ? " · " + esc(last.survey.method) : ""}</span>` : ""}
          <span class="tear"></span>
          <span class="row-between">${pill(p.confidence, true, { high: "High", medium: "Med", low: "Low" }[p.confidence])}${counts(p)}</span>
        </button>`;
      }).join("") + `</div>`;
    }).join("") + `</div></div>`;
  el.querySelectorAll(".ticket").forEach((t) => (t.onclick = () => select(t.dataset.id)));
}

// ---------- ground truth ----------
function renderTruth() {
  const el = document.getElementById("truth");
  const rows = [];
  for (const [id, s] of Object.entries(state)) for (const v of s.visits || []) if (byId[id]) rows.push({ id, p: byId[id].properties, v, r: verdict(byId[id].properties, v) });
  rows.sort((a, b) => (b.v.date || "").localeCompare(a.v.date || ""));
  const judged = rows.filter((r) => r.r.kind !== "new"), hits = judged.filter((r) => r.r.kind === "match").length;
  const misses = rows.filter((r) => r.r.kind === "miss");
  const row = (r) => {
    const f = FOUND.find((x) => x[0] === r.v.found), icon = { match: IC.pass(), miss: IC.fail(), new: IC.unknown() }[r.r.kind];
    return `<button type="button" class="truth-row ${r.r.kind}" data-id="${r.id}"><span class="tile">${icon}</span>
      <span><b>#${plateText(r.p)} · ${esc(r.p.apn || r.p.label)}</b><br>${esc(f ? f[1] : r.v.found)}${r.v.buildings ? ` · ${esc(r.v.buildings)} building(s)` : ""}${r.v.survey ? ` · ${esc(r.v.survey.method)} survey` : ""}
      <br><span class="meta">${esc(r.r.text)}${r.v.note ? " · " + esc(r.v.note) : ""}</span></span><span class="meta">${esc(r.v.date)}</span></button>`;
  };
  el.innerHTML = `<div class="pane-head"><h2>Ground truth · ${esc(meta.city || "")}</h2><span class="meta">what site visits and existing-conditions surveys found, against what the public data predicted</span></div>
    <div class="stats">
      <div class="stat"><span class="label">Visits logged</span><span class="v">${rows.length}</span><span class="meta">site visits</span></div>
      <div class="stat"><span class="label">Surveys</span><span class="v">${rows.filter((r) => r.v.survey).length}</span><span class="meta">e.g. 3D scan</span></div>
      <div class="stat"><span class="label">Screen accuracy</span><span class="v">${judged.length ? Math.round((100 * hits) / judged.length) + "%" : "–"}</span><span class="meta">${hits} of ${judged.length} judged</span></div>
      <div class="stat"><span class="label">Error log</span><span class="v">${misses.length}</span><span class="meta">misses to learn from</span></div>
    </div>
    <div class="truth-list"><span class="label">Error log · where the data was wrong</span>${misses.length ? misses.map(row).join("") : '<div class="empty">No misses yet. Log a site visit from any site card.</div>'}
    <span class="label" style="margin-top:16px">All visits</span>${rows.length ? rows.map(row).join("") : '<div class="empty">No visits yet.</div>'}
    <p class="meta">Each miss is a correction to the public data and a test case for the screening thresholds (labelled ASSUMPTION). The more visits are logged, the better the next ranking gets.</p></div>`;
  el.querySelectorAll("[data-id]").forEach((t) => (t.onclick = () => select(t.dataset.id)));
}

function renderAll() {
  renderList();
  document.getElementById("rail").style.display = view === "rail" ? "block" : "none";
  document.getElementById("truth").style.display = view === "truth" ? "block" : "none";
  document.getElementById("saved").style.display = view === "saved" ? "block" : "none";
  if (view === "rail") renderRail();
  if (view === "truth") renderTruth();
  if (view === "saved") renderSaved();
  document.querySelectorAll(".tabs button").forEach((b) => b.setAttribute("aria-pressed", String(b.dataset.view === view)));
  if (selectedId && byId[selectedId] && document.getElementById("card").style.display === "block") renderCard(selectedId);
}
document.querySelectorAll(".tabs button").forEach((b) => (b.onclick = () => { view = b.dataset.view; renderAll(); if (view === "map") setTimeout(() => map.invalidateSize(), 50); }));

// ---------- site card ----------
function select(id, fly) {
  selectedId = id;
  const f = byId[id];
  if (fly && view === "map") {
    if (f.geometry.type === "Point") map.flyTo([f.geometry.coordinates[1], f.geometry.coordinates[0]], 17, { duration: 0.6 });
    else map.flyToBounds(L.geoJSON(f).getBounds(), { maxZoom: 18, duration: 0.6 });
  }
  document.getElementById("card").style.display = "block";
  renderAll();
}

function renderCard(id) {
  const p = byId[id].properties, s = siteState(id);
  const groups = {};
  for (const c of p.checks || []) (groups[c.group] ||= []).push(c);
  const lastVisit = s.visits[s.visits.length - 1];
  if (lastVisit) {
    const fv = FOUND.find((x) => x[0] === lastVisit.found), r = verdict(p, lastVisit);
    (groups["Still available?"] ||= []).unshift({ test: "Ground truth", status: fv && fv[2] === "built" ? "fail" : (fv && fv[2] !== "unknown" ? "pass" : "unknown"),
      detail: `${fv ? fv[1] : "Visited"} (${lastVisit.survey ? lastVisit.survey.method + " survey" : "site visit"}, ${lastVisit.date}). ${r.text}`, source: "Logged by the team", url: null });
  }
  const all = Object.values(groups).flat(), n = { pass: 0, fail: 0, unknown: 0 };
  all.forEach((c) => n[c.status]++);
  const checks = Object.entries(groups).map(([g, cs]) => `<div class="label group-label">${esc(g)}</div><div class="checks">` + cs.map((c) =>
    `<div class="check-row ${c.status}"><span class="tile" role="img" aria-label="${STATUS_WORD[c.status]}">${IC[c.status]()}</span><div><b>${esc(c.test)}</b>: ${esc(c.detail)}
     <div class="src">${c.url ? `<a href="${c.url}" target="_blank" rel="noopener">${esc(c.source)} ↗</a>` : esc(c.source)}</div></div></div>`).join("") + "</div>").join("");
  const assumptions = (p.assumptions || []).map((a) => `<li>${esc(a)}</li>`).join("");
  const facts = [p.kind === "surplus" && p.apn ? `APN ${esc(p.apn)}` : null, p.acres != null ? `${p.acres} ac` : null, esc(p.city)].filter(Boolean).join(" · ");
  const extra = [p.zoning ? `Zoning ${esc(p.zoning)}` : null, p.landuse_code ? `SCAG land use ${esc(p.landuse_code)}` : null,
                 p.agency ? `Agency ${esc(p.agency)}` : null, p.existing_use ? `Existing use: ${esc(p.existing_use)}` : null,
                 p.notice_date ? `Notice issued ${esc(p.notice_date)}` : null, p.case ? `Case ${esc(p.case)}` : null,
                 p.notice_link ? `<a href="${esc(p.notice_link)}" target="_blank" rel="noopener">Agency notice ↗</a>` : null].filter(Boolean).join(" · ");
  const visits = s.visits.slice().reverse().map((v) => {
    const fv = FOUND.find((x) => x[0] === v.found);
    return `<li><b>${esc(v.date)}</b> · ${esc(fv ? fv[1] : v.found)}${v.buildings ? ` · ${esc(v.buildings)} bldg` : ""}${v.survey ? ` · ${esc(v.survey.method)}${v.survey.sqft ? `, ${esc(v.survey.sqft)} sq ft` : ""}${v.survey.link ? ` · <a href="${esc(v.survey.link)}" target="_blank" rel="noopener">survey files</a>` : ""}` : ""}${v.note ? `<div class="meta">${esc(v.note)}</div>` : ""}</li>`;
  }).join("");
  const card = document.getElementById("card");
  card.innerHTML = `
    <div class="card-head"><span class="plate ${p.kind || ""}">${plateText(p)}</span>
      <div><h2>${esc(p.kind === "surplus" ? p.label : (p.apn ? "APN " + p.apn : p.label))}</h2><div class="meta">${p.kind === "surplus" ? "Surplus public land notice" : (p.kind === "checked" ? "Lot you checked · live public data, " + esc(p.checked_at || "") : "Housing-element site")}</div><div class="meta" style="white-space:nowrap">${facts}</div></div>
      <button type="button" class="star-btn" id="saveCard" aria-pressed="${isSaved(id)}" aria-label="${isSaved(id) ? "Remove from saved" : "Save site"}">${IC.star(isSaved(id))}</button>
      <button type="button" class="icon-btn" id="closeCard" aria-label="Close site card" style="margin-left:0">${IC.close}</button></div>
    <div class="card-tags">${pill(p.confidence)}${tag(s.station)}<span class="gridref">${gridRef(byId[id])}</span></div>
    <p>${esc(p.summary)}</p>
    ${extra ? `<div class="meta" style="margin-bottom:8px">${extra}</div>` : ""}
    <div class="actions"><button type="button" id="callBtn" class="btn btn-primary">Open call sheet${claudeOn ? " · Claude" : ""}</button>
      <button type="button" id="visitBtn" class="btn btn-ghost">Log site visit / survey</button></div>
    <div class="station-row"><label class="label" for="station">Station</label>
      <select class="select" id="station">${STATIONS.map(([k, nm]) => `<option value="${k}" ${k === s.station ? "selected" : ""}>${nm}</option>`).join("")}</select></div>
    <form id="visitForm" class="visit-form">
      <div class="field"><label class="label" for="v-date">Date</label><input class="input" id="v-date" type="date" name="date" required value="${new Date().toISOString().slice(0, 10)}"></div>
      <div class="field"><label class="label" for="v-found">What is actually on the lot</label><select class="select" id="v-found" name="found">${FOUND.map(([k, nm]) => `<option value="${k}">${nm}</option>`).join("")}</select></div>
      <div class="field"><label class="label" for="v-b">Buildings seen</label><input class="input" id="v-b" type="number" name="buildings" min="0" step="1" placeholder="optional"></div>
      <label class="check"><input type="checkbox" name="surveyed"> Existing-conditions survey done</label>
      <div class="survey">
        <div class="field"><label class="label" for="v-m">Method</label><select class="select" id="v-m" name="method"><option>3D scan</option><option>Tape / laser measure</option><option>Drone</option><option>Other</option></select></div>
        <div class="field"><label class="label" for="v-sq">Measured area (sq ft)</label><input class="input" id="v-sq" type="number" name="sqft" min="0" placeholder="optional"></div>
        <div class="field"><label class="label" for="v-l">Link to files (E57, PDF, DWG)</label><input class="input" id="v-l" type="url" name="link" placeholder="optional"></div>
      </div>
      <div class="field"><label class="label" for="v-n">Note</label><textarea class="textarea" id="v-n" name="note" rows="2" placeholder="What the data got wrong. No owner, tenant or other personal names."></textarea></div>
      <button class="btn btn-primary" type="submit">Save visit</button>
    </form>
    ${visits ? `<div class="label group-label">Visits</div><ul class="visits">${visits}</ul>` : ""}
    <div class="sec-head"><span class="label">Site checks</span><span class="meta">${n.pass} pass · ${n.fail} fail · ${n.unknown} unknown</span></div>
    ${checks}
    ${pathwaysHTML(p)}
    ${assumptions ? `<div class="label group-label">Assumed (our thresholds, not law)</div><ul class="visits">${assumptions}</ul>` : ""}
    <div class="verify"><b>Next step: verify on the ground.</b> ${p.kind === "surplus" ? "Surplus notices can be withdrawn or already disposed of." : "Housing-element lists are filed when the plan is adopted, so a site may have sold or been built since."} Confirm what is actually on the lot (site visit or existing-conditions survey), who owns it and whether they would sell, and check eligibility with the city. Screening tool, not a zoning determination.</div>`;
  card.querySelector("#closeCard").onclick = () => { card.style.display = "none"; selectedId = null; renderAll(); };
  card.querySelector("#station").onchange = (e) => setStation(id, e.target.value, "set on site card");
  const form = card.querySelector("#visitForm");
  card.querySelector("#visitBtn").onclick = () => form.classList.toggle("open");
  form.surveyed.onchange = (e) => form.querySelector(".survey").classList.toggle("open", e.target.checked);
  form.onsubmit = (e) => {
    e.preventDefault();
    const v = { date: form.date.value, found: form.found.value, buildings: form.buildings.value || null, note: form.note.value.trim() || null,
                survey: form.surveyed.checked ? { method: form.method.value, sqft: form.sqft.value || null, link: form.link.value || null } : null };
    s.visits.push(v);
    if ((FOUND.find((x) => x[0] === v.found) || [])[2] === "built") setStation(id, "dropped", "visit found the lot built out");
    else setStation(id, v.survey ? "surveyed" : (["to_call", "called", "screened"].includes(s.station) ? "visit" : s.station), v.survey ? "existing-conditions survey logged" : "site visit logged");
    saveState(); renderAll();
  };
  card.querySelector("#callBtn").onclick = () => openModal(id);
  card.querySelector("#saveCard").onclick = () => toggleSave(id);
}


// ---------- pathways (leads, not eligibility) ----------
// Each law has stacked site tests. Infill marks a test pass/fail only when a check it already
// runs answers it; everything else stays "unknown" with what would settle it. Sources: the lane
// brief (claude-impact-lab-uci, lanes/1-find-it) and the HCD fact sheets it links.
const SRC_LANE = ["Lane 1 brief (law list and SB 4 / SB 9 exclusions)", "https://github.com/travcjohnson/claude-impact-lab-uci/blob/main/lanes/1-find-it/README.md"];
const SRC_FACTS = ["HCD Housing Law Fact Sheets", "https://www.hcd.ca.gov/sites/default/files/docs/planning-and-community/housing-law-fact-sheets.pdf"];
const SRC_SB9 = ["HCD fact sheet: SB 9", "https://www.hcd.ca.gov/sites/default/files/docs/planning-and-community/lot-splits-and-duplexes-sb-9.pdf"];
const SRC_SB4 = ["HCD fact sheet: SB 4", "https://www.hcd.ca.gov/sites/default/files/docs/planning-and-community/aff-hsg-faith-higher-ed-sb-4.pdf"];
function pathways(p) {
  const chk = (name) => (p.checks || []).find((c) => c.test === name);
  const z = p.zoning ? `zoning code ${p.zoning}` : "zoning unknown";
  const fromCheck = (name, label, why) => {
    const c = chk(name);
    if (!c || c.status === "unknown") return { test: label, status: "unknown", detail: `${why}: not checked for this site` };
    return { test: label, status: c.status, detail: c.detail, source: c.source, url: c.url };
  };
  const owner = { test: "Owned by a faith organization or nonprofit college", status: "unknown", detail: "No free owner data. Confirm with the County Assessor; worship-site maps and the IRS exempt-organizations file are leads, not facts" };
  const list = [
    { id: "SB4", name: "SB 4", opens: "Housing on faith and nonprofit-college land", src: SRC_SB4,
      tests: [owner, fromCheck("Flood zone", "Not in a flood zone (SB 4 excludes flood zones)", "Flood zone"),
              fromCheck("Fire hazard zone", "Not in a fire hazard zone (SB 4 excludes fire zones; local zones only)", "Fire zone"),
              { test: "Not in a fault zone or wetland (also excluded)", status: "unknown", detail: "Not checked yet" }] },
    { id: "AB2011", name: "AB 2011", opens: "Housing on commercial corridors", src: SRC_FACTS,
      tests: [{ test: "Commercially zoned", status: "unknown", detail: `${z}: confirm with the city that it's a commercial zone` },
              { test: "Other site tests in the statute", status: "unknown", detail: "Not screened yet: read the statute before relying on this" }] },
    { id: "SB9", name: "SB 9", opens: "Lot splits and duplexes on single-family lots", src: SRC_SB9,
      tests: [{ test: "Single-family lot", status: "unknown", detail: `${z}: confirm it's a single-family zone` },
              { test: "Not in a historic district (SB 9 excludes them)", status: "unknown", detail: "Not checked yet" }] },
    { id: "SB684", name: "SB 684 / SB 1123", opens: "Small-lot subdivisions of up to 10 homes without a hearing", src: SRC_FACTS,
      tests: [{ test: "Lot size and zone limits", status: "unknown", detail: `${p.acres != null ? p.acres + " acres. " : ""}Limits differ by bill: cite the statute you use` }] },
    { id: "CONDO", name: "Condo conversion", opens: "Converting existing apartments to ownership condos", src: SRC_LANE,
      tests: [{ test: "Existing apartment building on the lot", status: "unknown", detail: "Not checked. Local condo-conversion rules apply" }] },
  ];
  for (const w of list) {
    const st = w.tests.map((t) => t.status);
    w.verdict = st.includes("fail") ? "ruled_out" : (st.includes("pass") ? "lead" : "unknown");
  }
  return list;
}
const VERDICT = { lead: ["Lead", "pass"], ruled_out: ["Ruled out by a site test", "fail"], unknown: ["Not screened yet", "unknown"] };
function pathwaysHTML(p) {
  return `<div class="sec-head"><span class="label">Pathways to check</span><span class="meta">leads, not eligibility</span></div>` +
    pathways(p).map((w) => `<details class="pathway"><summary><span class="pw-name">${esc(w.name)}</span><span class="pw-opens">${esc(w.opens)}</span>
      <span class="pw-v ${VERDICT[w.verdict][1]}">${VERDICT[w.verdict][0]}</span></summary>
      <div class="checks">${w.tests.map((t) => `<div class="check-row ${t.status}"><span class="tile" role="img" aria-label="${STATUS_WORD[t.status]}">${IC[t.status]()}</span><div><b>${esc(t.test)}</b>: ${esc(t.detail)}
        ${t.url ? `<div class="src"><a href="${t.url}" target="_blank" rel="noopener">${esc(t.source)} ↗</a></div>` : ""}</div></div>`).join("")}
      <div class="src" style="padding:6px 0 2px"><a href="${w.src[1]}" target="_blank" rel="noopener">${esc(w.src[0])} ↗</a></div></div></details>`).join("") +
    `<div class="meta" style="margin-top:6px">A lead means no checked test rules it out yet. Confirm every test with the city and the statute before acting.</div>`;
}

// ---------- call sheet ----------
const callCache = {};
function siteForClaude(p) {
  const s = siteState(p.id);
  return { kind: p.kind === "surplus" ? "surplus public land notice" : (p.kind === "checked" ? "parcel checked live by the user (may not be on any list)" : "adopted housing-element site"), city: p.city, label: p.label, apn: p.apn, acres: p.acres,
           zoning_code: p.zoning, scag_zoning_category: p.zoning_scag, scag_land_use_code: p.landuse_code, agency: p.agency, existing_use: p.existing_use,
           notice_status: p.status_text, lower_income_capacity_listed: p.low_income_capacity, total_capacity_listed: p.total_capacity,
           rank: p.rank, summary: p.summary,
           checks: p.checks.map((c) => ({ question: c.group, test: c.test, status: c.status, detail: c.detail, source: c.source })),
           pathways_to_check: pathways(p).map((w) => ({ law: w.name, opens: w.opens, status: VERDICT[w.verdict][0], tests: w.tests.map((t) => `${t.test}: ${t.status}`) })),
           assumptions: p.assumptions, site_visits: s.visits.map((v) => ({ date: v.date, found: (FOUND.find((x) => x[0] === v.found) || [])[1], survey: v.survey ? v.survey.method : null })),
           data_pulled: meta.pulled };
}
function templateSheet(p) {
  const by = (st) => p.checks.filter((c) => c.status === st);
  const ref = p.apn ? "APN " + p.apn : p.label;
  return { headline: `${ref} in ${p.city}: ${p.summary}.`,
    known: by("pass").concat(by("fail")).map((c) => `${c.test}: ${c.detail} (${c.source})`).slice(0, 5),
    unknown: by("unknown").map((c) => `${c.test}: ${c.detail}`).concat(["Who owns the site and whether they would sell", "Water and sewer capacity", "Contamination history"]).slice(0, 5),
    ask_city: ["Is this site still available as listed?", "Which objective standards apply (parking, setbacks, height)?", "Is the site eligible for any streamlined approval path?", "Who in housing or planning staff handles affordable projects on this site?"],
    ask_on_site: ["What is on the lot today (buildings, parking, vacant)?", "Access, curb cuts and street frontage", "Visible utilities (power poles, meters, manholes)", "Grade changes, trees or easements visible on site"],
    email_subject: `Question about ${p.kind === "surplus" ? "surplus land notice" : "housing element site"} ${ref}`,
    email_body: `Hello,\n\nI work with [nonprofit name], an affordable housing nonprofit. ${p.kind === "surplus" ? `We saw ${ref} in the state's surplus land notices.` : `Your adopted housing element lists ${ref} with capacity for ${p.low_income_capacity} lower-income homes.`} Could you tell me whether the site is still available, and who we should talk to about it?\n\nThank you,\n[name]\n[phone]`,
    model: "template (no Claude key set)" };
}
async function callSheet(id) {
  const p = byId[id].properties;
  let sheet;
  if (claudeOn) {
    try {
      const r = await fetch("/api/callsheet", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ site: siteForClaude(p) }) });
      const j = await r.json();
      if (!r.ok) throw new Error(j.error || r.status);
      sheet = j;
    } catch (e) { sheet = templateSheet(p); sheet.model = `template (Claude call failed: ${e.message})`; }
  } else sheet = templateSheet(p);
  callCache[id] = sheet;
  if (modalId === id) renderModal(id);
}
// ---------- call sheet window ----------
let modalId = null;
const modalEl = document.getElementById("modal");
function openModal(id) {
  modalId = id; modalEl.hidden = false; document.body.style.overflow = "hidden";
  renderModal(id);
  if (!callCache[id]) callSheet(id);
  setTimeout(() => modalEl.querySelector("#m-close")?.focus(), 0);
}
function closeModal() { modalId = null; modalEl.hidden = true; modalEl.innerHTML = ""; document.body.style.overflow = ""; }
modalEl.addEventListener("click", (e) => { if (e.target === modalEl) closeModal(); });
document.addEventListener("keydown", (e) => { if (modalId && e.key === "Escape") closeModal(); });

function renderModal(id) {
  const f = byId[id], p = f.properties, s = siteState(id), c = callCache[id];
  const n = { pass: 0, fail: 0, unknown: 0 }; (p.checks || []).forEach((x) => n[x.status]++);
  const li = (xs) => (xs || []).map((x) => `<li>${esc(x)}</li>`).join("");
  const sk = '<div class="skeleton"></div><div class="skeleton" style="width:80%"></div><div class="skeleton" style="width:60%"></div>';
  const ref = p.kind === "surplus" ? p.label : (p.apn ? "APN " + p.apn : p.label);
  const known = (p.checks || []).map((x) => `<li><span class="tile ${x.status}">${IC[x.status]("#FFFFFF", 12)}</span><span><b>${esc(x.test)}</b>: ${esc(x.detail)}<br><span class="src">${x.url ? `<a href="${x.url}" target="_blank" rel="noopener">${esc(x.source)} ↗</a>` : esc(x.source)}</span></span></li>`).join("");
  const unknownList = c ? (c.unknown || []).map((x) => `<li><span class="tile">${IC.unknown("#FFFFFF", 12)}</span><span>${esc(x)}</span></li>`).join("") : sk;
  const keyNum = p.kind === "surplus" ? { label: "Status", v: p.active ? "Active" : "Archived", small: true }
                                      : { label: "Lower-income homes listed", v: String(p.low_income_capacity ?? "?") };
  modalEl.innerHTML = `<div class="modal" role="dialog" aria-modal="true" aria-labelledby="m-title">
    <div class="m-head">
      <span class="plate ${p.kind || ""}">${plateText(p)}</span>
      <div><h2 id="m-title">${esc(ref)}</h2>
        <div class="meta">Call sheet · ${p.kind === "surplus" ? "Surplus public land notice" : (p.kind === "checked" ? "Lot you checked" : "Housing-element site")} · ${esc(p.city)} · ${gridRef(f)}</div>
        <div class="card-tags" style="margin:10px 0 0">${pill(p.confidence)}${tag(s.station)}</div></div>
      <div class="m-head-actions no-print">
        <button type="button" class="star-btn" id="m-save" aria-pressed="${isSaved(id)}" aria-label="${isSaved(id) ? "Remove from saved" : "Save site"}">${IC.star(isSaved(id))}</button>
        <button type="button" class="icon-btn" id="m-close" aria-label="Close call sheet" style="margin:0">${IC.close}</button>
      </div>
    </div>
    <div class="m-headline">${c ? esc(c.headline) : esc(p.summary)}</div>
    <div class="m-stats">
      <div class="m-stat key"><span class="label">${keyNum.label}</span><span class="v ${keyNum.small ? "small" : ""}">${esc(keyNum.v)}</span>${p.total_capacity != null ? `<span class="meta">of ${p.total_capacity} total listed</span>` : ""}</div>
      <div class="m-stat"><span class="label">Lot size</span><span class="v">${p.acres != null ? p.acres : "?"}</span><span class="meta">acres</span></div>
      <div class="m-stat"><span class="label">Checks</span><span class="v small">${counts(p)}</span><span class="meta">pass · fail · unknown</span></div>
      <div class="m-stat"><span class="label">Zoning</span><span class="v small">${esc((p.zoning || "?").slice(0, 18))}</span><span class="meta">${p.landuse_code ? "SCAG land use " + esc(p.landuse_code) : (p.existing_use ? esc(p.existing_use.slice(0, 40)) : "&nbsp;")}</span></div>
    </div>
    <div class="m-body">
      <div>
        <div class="m-sec"><h3>Ask the city</h3>${c ? `<ol class="qlist">${li(c.ask_city)}</ol>` : sk}</div>
        <div class="m-sec"><h3>Still unknown</h3><ul class="ulist">${unknownList}</ul></div>
        <div class="m-sec"><h3>Look for on site</h3>${c ? `<ol class="qlist">${li(c.ask_on_site)}</ol>` : sk}</div>
      </div>
      <div>
        <div class="m-sec"><h3>What the data shows <span class="meta">pulled ${esc(meta.pulled || "?")}</span></h3><ul class="ulist">${known}</ul></div>
        <div class="m-sec"><h3>Draft email · not sent</h3>${c ? `<div class="m-email"><b>${esc(c.email_subject)}</b><pre>${esc(c.email_body)}</pre>
          <button type="button" class="btn btn-ghost btn-sm no-print" id="m-copy">Copy email</button></div>` : sk}</div>
      </div>
    </div>
    <div class="m-note meta">${c ? `Written by ${esc(c.model)} from the facts above only. Check before you rely on it.` : (claudeOn ? "Claude is writing the call sheet from this site's checks…" : "Building the call sheet…")} Prototype: screening only, not a zoning or legal determination.</div>
    <div class="m-foot no-print">
      <button type="button" class="btn btn-primary" id="m-called">${s.station === "called" ? "Marked as called ✓" : "Mark as called"}</button>
      <button type="button" class="btn btn-ghost" id="m-visit">Log site visit</button>
      <span class="spacer"></span>
      <a class="btn btn-ghost" href="${mapsLink(f)}" target="_blank" rel="noopener" style="text-decoration:none">Open in Maps ↗</a>
      <button type="button" class="btn btn-ghost" id="m-csv">Export CSV</button>
      <button type="button" class="btn btn-ghost" id="m-print">Print / PDF</button>
    </div>
  </div>`;
  modalEl.querySelector("#m-close").onclick = closeModal;
  modalEl.querySelector("#m-save").onclick = () => { toggleSave(id); renderModal(id); };
  modalEl.querySelector("#m-called").onclick = () => { setStation(id, "called", "marked as called from call sheet"); renderModal(id); };
  modalEl.querySelector("#m-visit").onclick = () => { closeModal(); select(id); document.getElementById("visitForm")?.classList.add("open"); };
  modalEl.querySelector("#m-csv").onclick = () => downloadCSV([siteRecord(id)], `infill-${(p.apn || p.id).replace(/[^\w-]/g, "")}.csv`);
  modalEl.querySelector("#m-print").onclick = () => printAs("print-modal");
  const cp = modalEl.querySelector("#m-copy");
  if (cp) cp.onclick = () => { navigator.clipboard?.writeText(`${c.email_subject}\n\n${c.email_body}`); cp.textContent = "Copied ✓"; };
}

// ---------- save, export ----------
function centerOf(f) {
  if (f.geometry.type === "Point") return { lat: f.geometry.coordinates[1], lng: f.geometry.coordinates[0] };
  const c = L.geoJSON(f).getBounds().getCenter(); return { lat: c.lat, lng: c.lng };
}
const mapsLink = (f) => { const c = centerOf(f); return `https://www.google.com/maps/search/?api=1&query=${c.lat.toFixed(6)},${c.lng.toFixed(6)}`; };
function snapshot(id) {
  const f = byId[id], p = f.properties, c = centerOf(f);
  return { city_slug: city, city: p.city, kind: p.kind || "housing_element", rank: p.rank ?? null, apn: p.apn, label: p.label,
           acres: p.acres, lower_income_capacity: p.low_income_capacity ?? null, total_capacity: p.total_capacity ?? null,
           zoning: p.zoning, confidence: p.confidence, summary: p.summary, lat: +c.lat.toFixed(6), lng: +c.lng.toFixed(6),
           checks: (p.checks || []).map((x) => `${x.test}: ${x.status}`).join("; "), data_pulled: meta.pulled };
}
function toggleSave(id) {
  const s = siteState(id);
  if (s.saved) { s.saved = false; delete s.snapshot; s.log.push({ at: new Date().toISOString(), why: "removed from saved" }); }
  else { s.saved = true; s.saved_at = new Date().toISOString(); s.snapshot = snapshot(id); }
  saveState(); renderAll();
}
function siteRecord(id) {
  const snap = byId[id] ? snapshot(id) : state[id]?.snapshot || {};
  const s = state[id] || {};
  const last = s.visits?.[s.visits.length - 1];
  return { ...snap, id, station: stationName(s.station || defaultStation(id)), saved: s.saved ? "yes" : "no",
           last_visit: last ? `${last.date} ${(FOUND.find((x) => x[0] === last.found) || [])[1] || ""}${last.survey ? " (" + last.survey.method + ")" : ""}` : "",
           maps_link: `https://www.google.com/maps/search/?api=1&query=${snap.lat},${snap.lng}` };
}
function downloadCSV(rows, name) {
  if (!rows.length) return;
  const cols = ["id", "city", "kind", "rank", "apn", "label", "acres", "lower_income_capacity", "total_capacity", "zoning", "confidence", "station", "saved", "last_visit", "summary", "checks", "lat", "lng", "maps_link", "data_pulled"];
  const q = (v) => { const t = String(v ?? ""); return /[",\n]/.test(t) ? `"${t.replace(/"/g, '""')}"` : t; };
  const csv = [cols.join(","), ...rows.map((r) => cols.map((k) => q(r[k])).join(","))].join("\n");
  const url = URL.createObjectURL(new Blob([csv], { type: "text/csv" }));
  const a = document.createElement("a"); a.href = url; a.download = name; document.body.appendChild(a); a.click(); a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}
function printAs(cls) { document.body.classList.add(cls); window.print(); setTimeout(() => document.body.classList.remove(cls), 500); }

// ---------- saved sites ----------
async function openSaved(id, slug) {
  if (slug && slug !== city) { citySel.value = slug; await useCity(slug); }
  view = "map"; renderAll(); setTimeout(() => map.invalidateSize(), 50);
  if (byId[id]) select(id, true);
}
function renderSaved() {
  const el = document.getElementById("saved");
  const items = Object.entries(state).filter(([, s]) => s.saved && s.snapshot).map(([id, s]) => ({ id, s, snap: s.snapshot }))
    .sort((a, b) => (b.s.saved_at || "").localeCompare(a.s.saved_at || ""));
  const byCity = {};
  items.forEach((x) => (byCity[x.snap.city] ||= []).push(x));
  el.innerHTML = `<div class="pane-head"><h2>Saved sites · ${items.length}</h2>
      <div class="actions no-print" style="margin:0"><button type="button" class="btn btn-ghost btn-sm" id="sv-csv" ${items.length ? "" : "disabled"}>Export all (CSV)</button>
      <button type="button" class="btn btn-ghost btn-sm" id="sv-print" ${items.length ? "" : "disabled"}>Print / PDF</button></div></div>
    <div class="saved-wrap">${items.length ? Object.entries(byCity).map(([cname, xs]) => `<span class="label" style="margin-top:8px">${esc(cname)} · ${xs.length}</span>` + xs.map(({ id, s, snap }) => `
      <div class="saved-row"><div>
        <div class="lr-top"><span class="mono" style="color:var(--color-muted)">${snap.kind === "surplus" ? "SL" : String(snap.rank ?? "").padStart(2, "0")}</span><span class="lr-apn">${esc(snap.apn || snap.label)}</span>${pill(snap.confidence, true, { high: "High", medium: "Med", low: "Low" }[snap.confidence])}${tag(s.station || "screened", true)}</div>
        <div style="margin-top:4px">${esc(snap.summary)}</div>
        <div class="meta">${snap.acres != null ? snap.acres + " ac · " : ""}${snap.lat}, ${snap.lng} · saved ${esc((s.saved_at || "").slice(0, 10))}</div></div>
        <div class="acts no-print"><button type="button" class="btn btn-primary btn-sm" data-open="${id}" data-city="${snap.city_slug}">Open</button>
          <a class="btn btn-ghost btn-sm" style="text-decoration:none" href="https://www.google.com/maps/search/?api=1&query=${snap.lat},${snap.lng}" target="_blank" rel="noopener">Maps ↗</a>
          <button type="button" class="btn btn-ghost btn-sm" data-unsave="${id}">Remove</button></div>
      </div>`).join("")).join("") : '<div class="empty">No saved sites yet. Use the star on a site card or call sheet.</div>'}</div>`;
  el.querySelectorAll("[data-open]").forEach((b) => (b.onclick = () => openSaved(b.dataset.open, b.dataset.city)));
  el.querySelectorAll("[data-unsave]").forEach((b) => (b.onclick = () => { const s = state[b.dataset.unsave]; s.saved = false; delete s.snapshot; saveState(); renderAll(); }));
  const csvB = el.querySelector("#sv-csv"); if (csvB) csvB.onclick = () => downloadCSV(items.map((x) => siteRecord(x.id)), "infill-saved-sites.csv");
  const prB = el.querySelector("#sv-print"); if (prB) prB.onclick = () => printAs("print-saved");
}


// ---------- check any lot (live, via scripts/serve.py) ----------
const checkMsg = (t) => (document.getElementById("checkMsg").textContent = t || "");
async function checkAt(lat, lng, label) {
  if (!server) { checkMsg("Live checks need the local server: run python3 scripts/serve.py"); return; }
  checkMsg(`Checking ${label || "this lot"} against live public data…`);
  try {
    const r = await fetch(`/api/check?lat=${lat}&lng=${lng}`), j = await r.json();
    if (!r.ok) throw new Error(j.error || r.status);
    const id = j.properties.id;
    if (!byId[id]) { checked.unshift(j); byId[id] = j; }
    checkMsg(`Checked ${j.properties.label}${j.properties.city ? " · " + j.properties.city : ""}`);
    view = "map"; select(id, true);
  } catch (e) { checkMsg(`Couldn't check: ${e.message}`); }
}
map.on("click", (e) => {
  if (view !== "map") return;
  const btn = document.createElement("button");
  btn.className = "btn btn-ghost btn-sm"; btn.type = "button"; btn.textContent = "Check this lot";
  btn.onclick = () => { map.closePopup(); checkAt(e.latlng.lat.toFixed(6), e.latlng.lng.toFixed(6)); };
  L.popup({ closeButton: false }).setLatLng(e.latlng).setContent(btn).openOn(map);
});
document.getElementById("checkForm").onsubmit = async (e) => {
  e.preventDefault();
  const q = document.getElementById("checkAddr").value.trim();
  if (!q) return;
  if (!server) { checkMsg("Address checks need the local server: run python3 scripts/serve.py"); return; }
  checkMsg("Finding the address…");
  try {
    const r = await fetch(`/api/geocode?q=${encodeURIComponent(q)}`), j = await r.json();
    if (!r.ok) throw new Error(j.error || r.status);
    await checkAt(j.lat, j.lng, j.matched);
  } catch (err) { checkMsg(`Couldn't find it: ${err.message}`); }
};

// ---------- start ----------
(async () => {
  await loadState();
  let start = null;
  try { start = localStorage.getItem("infill-city"); } catch {}
  if (!CITY_INDEX.find((c) => c.slug === start)) start = CITY_INDEX[0]?.slug;
  if (start) { citySel.value = start; await useCity(start); } else renderAll();
})();
